-- Clean up old active sets to avoid duplication
UPDATE public.screening_question_sets SET is_active = false;

-- Ensure domains exist (using ON CONFLICT DO UPDATE on slug to make it robust)
DO $$
DECLARE
  fs_id UUID;
  ai_id UUID;
  fe_id UUID;
  be_id UUID;
  cs_id UUID;
  ds_id UUID;
  set_id UUID;
BEGIN
  -- Upsert Domains
  ON CONFLICT (slug) DO UPDATE SET is_active = true, name = EXCLUDED.name RETURNING id INTO fs_id;

  ON CONFLICT (slug) DO UPDATE SET is_active = true, name = EXCLUDED.name RETURNING id INTO ai_id;

  ON CONFLICT (slug) DO UPDATE SET is_active = true, name = EXCLUDED.name RETURNING id INTO fe_id;

  ON CONFLICT (slug) DO UPDATE SET is_active = true, name = EXCLUDED.name RETURNING id INTO be_id;

  ON CONFLICT (slug) DO UPDATE SET is_active = true, name = EXCLUDED.name RETURNING id INTO cs_id;

  ON CONFLICT (slug) DO UPDATE SET is_active = true, name = EXCLUDED.name RETURNING id INTO ds_id;

  -- 1. Full Stack Development
  -- D1

  -- D2

  -- D3

  -- 2. Artificial Intelligence
  -- D1

  -- D2

  -- D3

  -- 3. Frontend Development
  -- D1

  -- D2

  -- D3

  -- 4. Backend Development
  -- D1

  -- D2

  -- D3

  -- 5. Cybersecurity
  -- D1

  -- D2

